insert into public.schools(name,country,type,category,city,website,verified,demo,admission_info,admission_link,admission_checked)
select 'Northeastern University London','United Kingdom','Private','University','London','https://www.nulondon.ac.uk/',false,false,'{"ug": "Northeastern University London (formerly New College of the Humanities) is a private university in London. English: IELTS Academic 6.5 with at least 6.0 in each part, TOEFL iBT 4.5 on the new 1-6 scale (at least 4 in each part), or Duolingo 115 (at least 105 in each part); undergraduates who took higher-level English at secondary school may be exempt. International tuition for 2027-28: GBP 24,573 a year for Economics, Law, Philosophy, Psychology, and Politics and International Relations; GBP 29,263 a year for Business, Data Science, Computer Science and Business, and Philosophy and Computer Science.", "sources": ["https://www.nulondon.ac.uk/admissions/entry-requirements/"]}'::jsonb,'https://www.nulondon.ac.uk/admissions/entry-requirements/',date '2026-11-27'
where not exists (select 1 from public.schools where name='Northeastern University London' and country='United Kingdom');
