-- ===== B. Government scholarships =====

insert into public.scholarships(name,funder,country,funding_type,level,criteria,link,verified,demo,field,source_url,award_note)
select 'Japanese Government (MEXT) Scholarship: Undergraduate Students','Ministry of Education, Culture, Sports, Science and Technology (MEXT), Japan','Japan','Full','Undergraduate','Who is eligible: Citizens of countries with diplomatic relations with Japan, born on or after 2 April 2002 (2027 round), who have finished 12 years of school (or will by March 2027). Requirements: Willing to learn Japanese; most grantees first take a one-year Japanese preparatory course and then study in Japanese. Art and music are not covered. The scholarship runs about five years (seven for medicine and dentistry). How to apply: Through the Japanese embassy in your country (embassy recommendation): document screening, written exams and an interview at the embassy, then final selection by MEXT. Do not send documents to MEXT in Japan. Deadline: The 2027 round closed in mid-2026 (each embassy sets its own date, usually April to June). Note: In the 2026 and 2027 rounds the Embassy of Japan in Ghana advertised the Research Students and Teacher Training categories on its website; we did not find a Ghana notice for the undergraduate category. Ask the Embassy of Japan in Ghana or the Ghana Scholarships Secretariat before planning on it.','https://www.studyinjapan.go.jp/en/smap-stopj-applications-undergraduate.html',false,false,null,'https://www.studyinjapan.go.jp/en/_mt/2026/04/2027_Guidelines_Undergraduate_E.pdf','Monthly allowance of JPY 117,000 (2027 guidelines; may change each year), entrance exam, matriculation and tuition fees waived, economy air ticket to Japan, and a ticket home on application after graduating.'
where not exists (select 1 from public.scholarships where name='Japanese Government (MEXT) Scholarship: Undergraduate Students');
insert into public.scholarships(name,funder,country,funding_type,level,criteria,link,verified,demo,field,source_url,award_note)
select 'Japanese Government (MEXT) Scholarship: Research Students (Master''s and PhD)','Ministry of Education, Culture, Sports, Science and Technology (MEXT), Japan','Japan','Full','Postgraduate','Who is eligible: Ghanaian citizens born on or after 2 April 1992 who want to do a master''s or doctoral course at a Japanese graduate school (2026 Ghana notice). A bachelor''s degree (16 years of schooling) is needed for master''s study. Requirements: Willing to learn Japanese; certified copies of degree certificates (certified by the awarding institution) and original transcripts. Only shortlisted applicants are contacted and asked for a medical certificate. How to apply: Download the current year''s forms from Study in Japan and send the completed application to The Registrar, Scholarships Secretariat, P.O. Box M75, Accra. Deadline: The 2026 Ghana round closed on 29 May 2026. The next round is usually announced around April. Note: The scholarship lasts about 18 months to two years for the Ghana embassy route, including 6 months of Japanese study; the schedule can change or be cancelled.','https://www.gh.emb-japan.go.jp/itpr_ja/11_000001_00538.html',false,false,null,'https://www.mh.emb-japan.go.jp/files/101016370.pdf','Monthly allowance of JPY 144,000 for master''s students and JPY 145,000 for doctoral students (JPY 143,000 while a non-regular research student), tuition and entrance fees waived, economy air ticket to Japan.'
where not exists (select 1 from public.scholarships where name='Japanese Government (MEXT) Scholarship: Research Students (Master''s and PhD)');
insert into public.scholarships(name,funder,country,funding_type,level,criteria,link,verified,demo,field,source_url,award_note)
select 'Global Korea Scholarship (GKS): Undergraduate Degrees','National Institute for International Education (NIIED), Republic of Korea','South Korea','Full','Undergraduate','Who is eligible: Applicant and both parents hold non-Korean citizenship; under 25 years old; high school graduate (or about to graduate) with a cumulative score of 80% or higher, or a place in the top 20% of the class. Requirements: One year of Korean language training first, then a 4 to 6 year bachelor''s degree. You cannot change your field after final selection. How to apply: Embassy track (through the Korean embassy in your country, if your country has a quota that year) or university track (directly to a participating university), online at www.studyinkorea.go.kr. Deadline: Guidelines come out in September each year; the embassy track closes in late September and the university track runs September to November. Final results in December. Note: Quotas differ by country each year. Check the Embassy of the Republic of Korea in Ghana for whether Ghana has an embassy-track quota.','https://www.studyinkorea.go.kr/ko/plan/scholarship.do',false,false,null,'https://www.studyinkorea.go.kr/ko/plan/scholarship.do','Airfare, one year of Korean language training, tuition and a monthly allowance (amounts are set in each year''s guidelines).'
where not exists (select 1 from public.scholarships where name='Global Korea Scholarship (GKS): Undergraduate Degrees');
insert into public.scholarships(name,funder,country,funding_type,level,criteria,link,verified,demo,field,source_url,award_note)
select 'Global Korea Scholarship (GKS): Graduate Degrees','National Institute for International Education (NIIED), Republic of Korea','South Korea','Full','Postgraduate','Who is eligible: Applicant and both parents hold non-Korean citizenship; under 40 years old; holds a bachelor''s degree (for master''s) or master''s degree (for PhD) with an average of at least 80% in the most recent programme. Requirements: One year of Korean language training, then a 2-year master''s or 3-year doctorate. How to apply: Through the Korean embassy in your country or through a participating university, online at www.studyinkorea.go.kr. Deadline: Guidelines come out in February each year; applications February to March; final results in June. Note: The Embassy of the Republic of Korea in Ghana has posted GKS graduate notices in past years; check its website when the new round opens.','https://www.studyinkorea.go.kr/ko/plan/scholarship.do',false,false,null,'https://www.studyinkorea.go.kr/ko/plan/scholarship.do','Airfare, one year of Korean language training, tuition and a monthly allowance (amounts are set in each year''s guidelines).'
where not exists (select 1 from public.scholarships where name='Global Korea Scholarship (GKS): Graduate Degrees');
insert into public.scholarships(name,funder,country,funding_type,level,criteria,link,verified,demo,field,source_url,award_note)
select 'Chinese Government Scholarship (Type A, through Ghana Scholarships Secretariat)','China Scholarship Council (CSC) and Ghana Scholarships Secretariat','China','Full','Postgraduate','Who is eligible: Ghanaian citizens living in Ghana. Master''s: first degree of at least Second Class Upper in a relevant field, age 35 or under. PhD: at least Second Class Upper plus a relevant master''s, age 40 or under. Must be medically fit. Women are particularly encouraged to apply. Requirements: Certified certificates and transcripts, study plan and 800-word research proposal, two recommendation letters from professors or associate professors, birth certificate, National Service certificate, CV, passport page; pre-admission letter and HSK, IELTS or TOEFL results if you have them. How to apply: Apply online at www.campuschina.org (Programme Category Type A, Agency Number 2881), then send hard copies to The Registrar, Ghana Scholarships Secretariat, P.O. Box M75, Accra. Deadline: For 2026/2027 the online deadline was 30 November 2025 and hard copies were due 18 December 2025. Watch the Secretariat''s site for the next round. Note: Awards are very limited and only shortlisted applicants are interviewed. This Ghana route covers master''s and PhD study only.','https://scholarships.gov.gh/opportunities/chinese-government-scholarship-awards-to-ghanaian-students-for-20262027-academic-year',false,false,null,'https://cie.ecust.edu.cn/chinese_government_scholarship/','Full scholarship: tuition waived, free university accommodation (or an accommodation subsidy), a monthly stipend of CNY 3,000 for master''s and CNY 3,500 for doctoral students, and medical insurance.'
where not exists (select 1 from public.scholarships where name='Chinese Government Scholarship (Type A, through Ghana Scholarships Secretariat)');

